  8918  /* Implementation of ofpact_finish_<ENUM>().
  8919   *
  8920   * Finishes composing a variable-length action (begun using
  8921   * ofpact_put_<NAME>()), by padding the action to a multiple of OFPACT_ALIGNTO
  8922   * bytes and updating its embedded length field.  See the large comment near
  8923   * the end of ofp-actions.h for more information.
  8924   *
  8925   * May reallocate 'ofpacts'. Callers should consider updating their 'ofpact'
  8926   * pointer to the return value of this function. */
  8927  void *
  8928  ofpact_finish(struct ofpbuf *ofpacts, struct ofpact *ofpact)
  8929  {
  8930      ptrdiff_t len;
  8931
  8932      ovs_assert(ofpact == ofpacts->header);
  8933      len = (char *) ofpbuf_tail(ofpacts) - (char *) ofpact;
  8934      ovs_assert(len > 0 && len <= UINT16_MAX);
  8935      ofpact->len = len;
  8936      ofpbuf_padto(ofpacts, OFPACT_ALIGN(ofpacts->size));
  8937
  8938      return ofpacts->header;
